class Cart {
  final List<Item> _items = [];      // private to this library
  double _total = 0;

  List<Item> get items => List.unmodifiable(_items); // read-only view
  double get total => _total;
  bool get isEmpty => _items.isEmpty;

  void add(Item item) {              // the only way in
    _items.add(item);
    _total += item.price;
  }

  set discount(double percent) {     // setter with validation
    if (percent < 0 || percent > 100) {
      throw ArgumentError.value(percent, 'percent');
    }
    _total *= 1 - percent / 100;
  }
}

